schema_ddl:
CREATE TABLE utenti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE ordini (
    id SERIAL PRIMARY KEY,
    utente_id INT NOT NULL,
    ordine_padre_id INT,
    totale NUMERIC(12,2) NOT NULL CHECK (totale >= 0),
    stato TEXT NOT NULL CHECK (stato IN ('in_attesa', 'confermato', 'spedito', 'consegnato', 'annullato'))
);

CREATE TABLE articoli_ordine (
    id SERIAL PRIMARY KEY,
    ordine_id INT NOT NULL,
    prodotto TEXT NOT NULL,
    quantita INT NOT NULL CHECK (quantita > 0),
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0)
);
